css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a{ color: #018E34; text-decoration: none; }
.dcx a:hover{ color: #016E28; }
.dcx :focus-visible{ outline: 2px solid #2FCB74; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-two],.dcx [data-conn],.dcx [data-solwrap],.dcx [data-cta]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-two] > *,.dcx [data-conn] > *{ justify-self: center; }
.dcx #ps-orbit{ max-width: 620px !important; }
.dcx #ps-conn{ max-width: 700px !important; }
.dcx [data-mods]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-sols]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 46px !important; }
.dcx [data-h2]{ font-size: 28px !important; }
}
@media (max-width: 640px){.dcx [data-mods],.dcx [data-sols]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-stats]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 34px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
.dch-5490d8da:focus{left: 12px !important;top: 12px !important}
.dch-a2297708:hover{background: #017129 !important;color: #fff !important}
.dch-52e2e147:hover{background: #F4F6F9 !important;color: #0A1330 !important}
.dch-d202569c:hover{background: #E9EEF2 !important;color: #0A1330 !important}
@media (max-width: 480px){.dcx [data-stats]{ grid-template-columns: minmax(0, 1fr) !important; }
}
